function deepestLeftmost(root: TreeNode | null): number {
  const queue: TreeNode[] = [root!];
  let ans = root!.val;
  for (let h = 0; h < queue.length; h++) {
    const node = queue[h];
    ans = node.val;
    if (node.right) queue.push(node.right);
    if (node.left) queue.push(node.left);
  }
  return ans;
}

