    def deepestLeftmost(self, root: Optional[TreeNode]) -> int:
        q = deque([root])
        ans = root.val
        while q:
            node = q.popleft()
            ans = node.val
            if node.right:
                q.append(node.right)
            if node.left:
                q.append(node.left)
        return ans

