function deepestLeftmost(root: TreeNode | null): number {
  let bestDepth = -1, ans = 0;
  const stack: [TreeNode, number][] = [[root!, 0]];
  while (stack.length) {
    const [node, d] = stack.pop()!;
    if (d > bestDepth) { bestDepth = d; ans = node.val; }
    // push right first so the left subtree is explored first
    if (node.right) stack.push([node.right, d + 1]);
    if (node.left) stack.push([node.left, d + 1]);
  }
  return ans;
}

